def make_grid(vec,color):
    g=[]
    for r in range(13):
        row=[]
        for c in range(14):
            if c in (2,5,8,11): row.append(0)
            else: row.append(color)
        g.append(row)
    for i, s in enumerate(vec):
        r=1+2*i
        for ch,(a,b) in zip(s,[(0,1),(3,4),(6,7),(9,10),(12,13)]):
            g[r][a]=0 if ch=='C' else color
            g[r][b]=color if ch=='A' else 0
    return g
def decode(g):
    return tuple(''.join('C' if g[1+2*i][a]==0 else ('B' if g[1+2*i][b]==0 else 'A') for a,b in [(0,1),(3,4),(6,7),(9,10),(12,13)]) for i in range(6))
checks=[]
