def life(mat,wrap=False):
 out=[]
 for r in range(6):
  rr=[]
  for c in range(5):
   n=0
   for dy in [-1,0,1]:
    for dx in [-1,0,1]:
     if not (dy or dx):continue
     y,x=r+dy,c+dx
     if wrap: n+=mat[y%6][x%5]
     elif 0<=y<6 and 0<=x<5:n+=mat[y][x]
   rr.append(int(n==3 or (mat[r][c] and n==2)))
  out.append(rr)
 return out
