def bit_mats():
 for ins,outs in samples_vec:
  yield [[int(ch=='A') for ch in row] for row in ins], [[int(ch=='A') for ch in row] for row in outs]
def transform_binary(m,kind):
 h=len(m);w=len(m[0]);o=[[0]*w for _ in range(h)]
 for r in range(h):
  for c in range(w):
   if kind=='rowprefix': o[r][c]=sum(m[r][:c+1])%2
   elif kind=='colprefix': o[r][c]=sum(m[:r+1][i][c] for i in range(r+1))%2
   elif kind=='2dprefix': o[r][c]=sum(m[i][j] for i in range(r+1) for j in range(c+1))%2
   elif kind=='rowdiff': o[r][c]=m[r][c]^(m[r][c-1] if c else 0)
   elif kind=='coldiff': o[r][c]=m[r][c]^(m[r-1][c] if r else 0)
   elif kind=='2ddiff': o[r][c]=m[r][c]^(m[r-1][c] if r else 0)^(m[r][c-1] if c else 0)^(m[r-1][c-1] if r and c else 0)
 return o
for kind in ['rowprefix','colprefix','2dprefix','rowdiff','coldiff','2ddiff']:
 print(kind, [transform_binary(x,kind)==y for x,y in bit_mats()])

